vetted_sources = [
    {"id": "v1", "text": "Staying hydrated and resting supports recovery from a mild common cold.", "trusted": True},
]

URGENT_KEYWORDS = ["chest pain", "difficulty breathing", "severe bleeding"]

def is_urgent(query):
    # urgent symptoms bypass normal retrieval and escalate immediately
    return any(k in query.lower() for k in URGENT_KEYWORDS)

def retrieve_vetted(query, sources):
    # only trusted, vetted sources are retrieved
    return [s for s in sources if s["trusted"] and any(w in s["text"].lower() for w in query.lower().split())]

def healthcare_respond(query, sources):
    if is_urgent(query):
        return "This may be a medical emergency. Please seek immediate emergency care or call emergency services."

    matches = retrieve_vetted(query, sources)
    disclaimer = "This information is general and does not replace advice from a qualified healthcare professional."
    if not matches:
        return f"I don't have vetted information on this. {disclaimer}"
    return f"{matches[0]['text']} {disclaimer}"

print("Healthcare assistant example:")
print(healthcare_respond("How do I recover from a common cold?", vetted_sources))
print()
print(healthcare_respond("I am having chest pain and difficulty breathing", vetted_sources))
